function Step-Version {
    <#
    .SYNOPSIS
        Applies a bump type to a semantic version string.
    .PARAMETER Version
        Current version in MAJOR.MINOR.PATCH form.
    .PARAMETER BumpType
        One of major / minor / patch / none.
    #>
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Version,

        [Parameter(Mandatory)]
        [ValidateSet('major', 'minor', 'patch', 'none')]
        [string]$BumpType
    )

    if ($Version -notmatch '^(\d+)\.(\d+)\.(\d+)$') {
        throw "'$Version' is not a valid semantic version (expected MAJOR.MINOR.PATCH, e.g. 1.2.3)."
    }
    $major, $minor, $patch = [int]$Matches[1], [int]$Matches[2], [int]$Matches[3]

    switch ($BumpType) {
        'major' { return "$($major + 1).0.0" }
        'minor' { return "$major.$($minor + 1).0" }
        'patch' { return "$major.$minor.$($patch + 1)" }
        'none'  { return $Version }
    }
}

Export-ModuleMember -Function Get-BumpType, Step-Version

